// Revisa el pedido y devuelve un ítem por cada jugador al que hay que avisar.
const entrada = $input.first().json;
const encabezados = entrada.headers || {};
const cuerpo = entrada.body || {};

const rechazo = (codigo, motivo) => [{ json: { valido: false, codigo, motivo } }];

const secretoRecibido = encabezados['x-f5gol-secreto'] || '';
if (entrada.secreto_esperado && secretoRecibido !== entrada.secreto_esperado) {
  return rechazo(401, 'El secreto del encabezado X-F5GOL-Secreto no es válido.');
}
if (cuerpo.evento !== 'partido.incompleto') {
  return rechazo(422, 'Evento desconocido: se esperaba partido.incompleto.');
}

const esMail = (m) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(m || '');
const jugadores = (cuerpo.jugadores || []).filter(j => esMail(j.email));
if (jugadores.length === 0) {
  return rechazo(422, 'No hay jugadores con un email válido para avisar.');
}

const turno = cuerpo.turno || {};
const cancha = cuerpo.cancha || {};
const club = cuerpo.club || {};
const links = cuerpo.links || {};

return jugadores.map(j => {
  const nombre = String(j.nombre || '').trim().split(/\s+/)[0] || 'crack';
  const extra = Number(j.cantidad_jugadores || 1) - 1;
  return {
    json: {
      valido: true,
      codigo: 200,
      email: String(j.email).toLowerCase(),
      nombre,
      con_amigos: (j.tipo === 'equipo' ? `Reservaste el Equipo ${j.equipo || 'A'} entero.`
        : `Jugás en el Equipo ${j.equipo || 'A'}.` + (extra > 0 ? ` Te anotaste con ${extra} ${extra === 1 ? 'amigo' : 'amigos'}.` : '')),
      dia: turno.dia || turno.fecha || '',
      horario: `${turno.hora_inicio || ''} a ${turno.hora_fin || ''}`,
      cupo: turno.cupo_maximo || '',
      anotados: turno.anotados || 0,
      cancha: cancha.nombre || 'la cancha',
      club: club.nombre || '',
      direccion: club.direccion || '',
      telefono: club.telefono || '',
      link: links.partidos || links.mis_reservas || '',
      remitente: entrada.remitente,
    },
  };
});

// Junta el resultado de todos los envíos en una sola respuesta para Laravel.
const mails = $('Armar mail').all().map(i => i.json.email);
const resultados = $input.all();
const fallidos = [];
resultados.forEach((r, i) => {
  if (r.json.error) {
    fallidos.push({ email: mails[i], error: r.json.error.message || String(r.json.error) });
  }
});
const enviados = resultados.length - fallidos.length;
return [{
  json: {
    ok: fallidos.length === 0,
    codigo: fallidos.length === 0 ? 200 : 502,
    mensaje: fallidos.length === 0
      ? (enviados === 1 ? 'Se avisó al jugador que el partido no se completó.' : `Se avisó a los ${enviados} jugadores que el partido no se completó.`)
      : `Se mandaron ${enviados} de ${resultados.length} mails; fallaron ${fallidos.length}.`,
    enviados,
    fallidos,
  },
}];
